package irvine.oeis.a400;

import irvine.math.group.AlternatingGroup;
import irvine.math.z.Z;
import irvine.oeis.Sequence1;

/**
 * A400417 Diameter of the directed Cayley graph of the alternating group A_(2n+1) generated by L = (0,1,...,2n) and T = (0,1,2).
 * @author Sean A. Irvine
 */
public class A400417 extends Sequence1 {

  private int mN = 0;

  @Override
  public Z next() {
    return Z.valueOf(AlternatingGroup.create(++mN).cayleyGraph().diameter());
  }
}
